/// <summary>
/// Base data contract for Azure processes
/// </summary>
[DataContract]
class OMGOutboundDataContract_Azure extends OMGDataContract_Azure
{
    FilenameType                fileType;
    OMGFilenamePattern          filenamePattern;

}

Method.Source:
[DataMember]
public FilenameType parmFileType(FilenameType _fileType = fileType)
{
    fileType = _fileType;
    return fileType;
}

[DataMember]
public OMGFilenamePattern parmFilenamePattern(OMGFilenamePattern _filenamePattern = filenamePattern)
{
    filenamePattern = _filenamePattern;
    return filenamePattern;
}
